from decimal import Decimal

gastos = [
    {"concepto": "Cuaderno", "importe": Decimal("4.50")},
    {"concepto": "Transporte", "importe": Decimal("2.50")},
    {"concepto": "Material", "importe": Decimal("10.00")},
]

def total_gastos(movimientos):
    return sum((g["importe"] for g in movimientos), Decimal("0.00"))

total = total_gastos(gastos)
print(f"Total: {total:.2f} EUR")
